using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// 6502 转译器
    /// </summary>
    public class Translator6502 : Translator8bit
    {
        public override string ARCH_NAME => "6502";
        protected override string CallMnemonic => "JSR";

        // 6502 中断上下文 (A, X, Y, P)
        protected override string[] ContextRegNames() => new string[0];
        protected override string NativeInt(int vector) => "brk";
        protected override string NativeIret() => "rti";
        protected override string NativeCli() => "sei";
        protected override string NativeSti() => "cli";
        protected override void EmitSaveContext()
        {
            Emit("        PHA");
            Emit("        TXA");
            Emit("        PHA");
            Emit("        TYA");
            Emit("        PHA");
            Emit("        PHP");
        }
        protected override void EmitRestoreContext()
        {
            Emit("        PLP");
            Emit("        PLA");
            Emit("        TAY");
            Emit("        PLA");
            Emit("        TAX");
            Emit("        PLA");
        }

        // VML 是32位指令集，6502 是8位架构
        // 虚拟寄存器映射到内存：R0=$00-$03, R1=$04-$07, ..., R15=$3C-$3F
        // 每个寄存器占4字节，低字节在前（小端序）
        private readonly Dictionary<int, string> REGISTER_MAP = new Dictionary<int, string>
        {
            { 0, "A" },   // 累加器
            { 1, "X" },   // 变址寄存器 X
            { 2, "Y" }    // 变址寄存器 Y
        };

        // 获取虚拟寄存器的内存基地址（用于32位操作）
        private string GetRegBaseAddr(int regNum) => $"${(regNum * 4):X2}";

        public Translator6502(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; 6502 Assembly - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("");
            Emit("        .processor 6502");
            Emit("        .org $0800");
            Emit("");
        }

        protected override void EmitCode()
        {
            Emit("        ; Code Section");
            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.JMP:
                    Emit($"        JMP {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                    Emit($"        BEQ {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                    Emit($"        BNE {instr.Operands[0].Value}");
                    break;
                case OpCode.JE:
                    Emit($"        BEQ {instr.Operands[0].Value}");
                    break;
                case OpCode.JNE:
                    Emit($"        BNE {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        BRK");
                    break;
                case OpCode.NOP:
                    Emit("        NOP");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit($"        LDA #{instr.Operands[0].Value}");
                    Emit("        BRK");
                    break;
                case OpCode.CATCH:
                    Emit($"        ; IRQ handler: {instr.Operands[0].Value}");
                    break;
                case OpCode.ENDCATCH:
                    break;

                // 浮点运算指令 (6502 无硬件浮点，使用软浮点库)
                case OpCode.FADD:
                    Emit("        ; FADD - 谯用软浮点加法库");
                    Emit("        JSR FP_ADD");
                    break;
                case OpCode.FSUB:
                    Emit("        ; FSUB - 谯用软浮点减法库");
                    Emit("        JSR FP_SUB");
                    break;
                case OpCode.FMUL:
                    Emit("        ; FMUL - 谯用软浮点乘法库");
                    Emit("        JSR FP_MUL");
                    break;
                case OpCode.FDIV:
                    Emit("        ; FDIV - 谯用软浮点除法库");
                    Emit("        JSR FP_DIV");
                    break;
                case OpCode.FNEG:
                    Emit("        ; FNEG - 符号位取反");
                    Emit("        LDA #$80");
                    Emit("        EOR FP_SIGN");
                    break;
                case OpCode.FCMP:
                    Emit("        ; FCMP - 谯用软浮点比较库");
                    Emit("        JSR FP_CMP");
                    break;

                // 浮点类型转换
                case OpCode.I2F:
                    Emit("        JSR FP_I2F");
                    break;
                case OpCode.F2I:
                    Emit("        JSR FP_F2I");
                    break;
                case OpCode.F2D:
                    Emit("        ; 单精度转双精度 (无操作，6502只有32位浮点)");
                    break;
                case OpCode.D2F:
                    Emit("        ; 双精度转单精度 (无操作)");
                    break;

                // 浮点数据传输
                case OpCode.MOVEF:
                                // MOVEF store path: dest != REGISTER → FSTORE (handled via goto from MOVEF above)
                                case OpCode.FPUSH:
                    Emit("        JSR FP_PUSH");
                    break;
                case OpCode.FPOP:
                    Emit("        JSR FP_POP");
                    break;

                // 算术指令 (6502 无 32 位硬件，用 zeropage/堆栈模拟)
                case OpCode.MUL:
                    Emit("        ; MUL - 32位乘法，通过 zeropage $80-$83");
                    Emit("        JSR MUL32");
                    break;
                case OpCode.DIV:
                    Emit("        ; DIV - 32位除法");
                    Emit("        JSR DIV32");
                    break;
                case OpCode.MOD:
                    Emit("        ; MOD - 32位模除");
                    Emit("        JSR MOD32");
                    break;
                case OpCode.INC:
                    Emit($"        ; INC - zeropage 增加");
                    Emit($"        INC ${instr.Operands[0].Value:X2}");
                    break;
                case OpCode.DEC:
                    Emit($"        ; DEC - zeropage 减少");
                    Emit($"        DEC ${instr.Operands[0].Value:X2}");
                    break;
                case OpCode.NEG:
                    Emit("        ; NEG - 累加器取反");
                    Emit("        EOR #$FF");
                    Emit("        CLC");
                    Emit("        ADC #$01");
                    break;

                // 逻辑指令
                case OpCode.AND:
                    Emit("        ; AND - 累加器 AND zeropage");
                    Emit("        JSR AND32");
                    break;
                case OpCode.OR:
                    Emit("        ; OR - 累加器 OR zeropage");
                    Emit("        JSR OR32");
                    break;
                case OpCode.XOR:
                    Emit("        ; XOR - 累加器 XOR zeropage");
                    Emit("        JSR XOR32");
                    break;
                case OpCode.NOT:
                    Emit("        ; NOT - 累加器取反");
                    Emit("        EOR #$FF");
                    break;
                case OpCode.TEST:
                    Emit("        ; TEST - 测试累加器");
                    Emit("        CMP #$00");
                    Emit("        ; Z flag set if A == 0");
                    break;

                // 位移指令
                case OpCode.SHL:
                    Emit("        ; SHL - 累加器左移");
                    Emit("        ASL A");
                    Emit("        ; C flag = shifted out bit");
                    break;
                case OpCode.SHR:
                    Emit("        ; SHR - 累加器逻辑右移");
                    Emit("        LSR A");
                    Emit("        ; C flag = shifted out bit");
                    break;

                // 栈和函数调用指令
                case OpCode.PUSH:
                    Emit($"        PHA");
                    break;
                case OpCode.POP:
                    Emit($"        PLA");
                    break;
                case OpCode.CALL:
                    Emit($"        JSR {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        RTS");
                    break;
                // case OpCode.RET_VAL:
                //     Emit("        ; RET_VAL - 返回值已在 A");
                //     Emit("        RTS");
                //     break;

                // 标签指令
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;

                // 比较跳转指令
                case OpCode.JL:
                    Emit($"        ; JL - 带符号小于跳转");
                    Emit("        JSR CMP32");
                    Emit($"        BMI {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        ; JLE - 带符号小于等于跳转");
                    Emit("        JSR CMP32");
                    Emit($"        BEQ {instr.Operands[0].Value}");
                    Emit($"        BMI {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        ; JG - 带符号大于跳转");
                    Emit("        JSR CMP32");
                    Emit($"        BPL {instr.Operands[0].Value}");
                    Emit($"        BNE {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        ; JGE - 带符号大于等于跳转");
                    Emit("        JSR CMP32");
                    Emit($"        BPL {instr.Operands[0].Value}");
                    break;

                // 系统调用 (ALLOC/FREE 通过 SYSCALL 40/41)
                case OpCode.SYSCALL:
                    Emit($"        ; SYSCALL {instr.Operands[0].Value}");
                    Emit("        JSR SYSCALL_HANDLER");
                    break;

                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("        ; ENTER: PUSH BP; MOVE BP,SP; SUB SP,size");
                        Emit("        PHA");
                        Emit("        TSX");
                        Emit("        STX BP_LO");
                        if (size > 0)
                            Emit($"        ; SUB SP, #{size}");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("        ; LEAVE: MOVE SP,BP; POP BP");
                    Emit("        LDX BP_LO");
                    Emit("        TXS");
                    Emit("        PLA");
                    break;

                // 标志位控制
                case OpCode.CLC:
                    Emit("        CLC");
                    break;
                case OpCode.STC:
                    Emit("        SEC");
                    break;

                // 内联汇编
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 地址计算
                                // 8位数据传输
                                                                                case OpCode.MOVEB:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstBase = GetRegBaseAddr(dstReg);
                            string srcBase = GetRegBaseAddr(srcReg);
                            Emit($"        ; MOVEB R{dstReg}, R{srcReg} (8-bit)");
                            Emit($"        LDA {srcBase}");
                            Emit($"        STA {dstBase}");
                        }
                    }
                    break;
                case OpCode.MOVEH:
                    {
                        var dst = instr.Operands[0];
                        var src = instr.Operands[1];
                        if (dst.Type == OperandType.REGISTER && src.Type == OperandType.REGISTER)
                        {
                            int dstReg = (int)dst.Value;
                            int srcReg = (int)src.Value;
                            string dstBase = GetRegBaseAddr(dstReg);
                            string srcBase = GetRegBaseAddr(srcReg);
                            Emit($"        ; MOVEW R{dstReg}, R{srcReg} (16-bit)");
                            Emit($"        LDA {srcBase}");
                            Emit($"        STA {dstBase}");
                            Emit($"        LDA {srcBase}+1");
                            Emit($"        STA {dstBase}+1");
                        }
                    }
                    break;
                case OpCode.PUSHB:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string regBase = GetRegBaseAddr(regNum);
                            Emit($"        ; PUSHB R{regNum} (8-bit)");
                            Emit($"        LDA {regBase}");
                            Emit($"        PHA");
                        }
                    }
                    break;
                case OpCode.PUSHH:
                    {
                        var src = instr.Operands[0];
                        if (src.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)src.Value;
                            string regBase = GetRegBaseAddr(regNum);
                            Emit($"        ; PUSHW R{regNum} (16-bit)");
                            Emit($"        LDA {regBase}+1");
                            Emit($"        PHA");
                            Emit($"        LDA {regBase}");
                            Emit($"        PHA");
                        }
                    }
                    break;
                case OpCode.POPB:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string regBase = GetRegBaseAddr(regNum);
                            Emit($"        ; POPB R{regNum} (8-bit, zero-extend)");
                            Emit($"        PLA");
                            Emit($"        STA {regBase}");
                            Emit($"        LDA #$00");
                            Emit($"        STA {regBase}+1");
                            Emit($"        STA {regBase}+2");
                            Emit($"        STA {regBase}+3");
                        }
                    }
                    break;
                case OpCode.POPH:
                    {
                        var dst = instr.Operands[0];
                        if (dst.Type == OperandType.REGISTER)
                        {
                            int regNum = (int)dst.Value;
                            string regBase = GetRegBaseAddr(regNum);
                            Emit($"        ; POPW R{regNum} (16-bit, zero-extend)");
                            Emit($"        PLA");
                            Emit($"        STA {regBase}");
                            Emit($"        PLA");
                            Emit($"        STA {regBase}+1");
                            Emit($"        LDA #$00");
                            Emit($"        STA {regBase}+2");
                            Emit($"        STA {regBase}+3");
                        }
                    }
                    break;

                // 调试
                case OpCode.BREAK:
                    Emit("        BRK");
                    break;

                case OpCode.ZERO:
                    {
                        int r = (int)instr.Operands[0].Value;
                        Emit($"        LDA #$00");
                        Emit($"        STA {GetRegBaseAddr(r)}");
                        Emit($"        STA {GetRegBaseAddr(r)}+1");
                        Emit($"        STA {GetRegBaseAddr(r)}+2");
                        Emit($"        STA {GetRegBaseAddr(r)}+3");
                    }
                    break;
                case OpCode.SHLV:
                    Emit("        JSR SHL32");
                    break;
                case OpCode.SHRV:
                    Emit("        JSR SHR32");
                    break;
                case OpCode.I2D:
                case OpCode.D2I:
                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 软件库
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        JSR FP_OP     ; {instr.Opcode}: {string.Join(", ", instr.Operands)}");
                    break;

                default:
                    Emit($"        ; UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (dst.Type == OperandType.REGISTER)
            {
                int regNum = (int)dst.Value;
                string regBase = GetRegBaseAddr(regNum);

                // 32位加载：4字节操作
                if (src.Type == OperandType.IMMEDIATE)
                {
                    int value = SafeToInt(src);
                    Emit($"        ; LOAD R{regNum}, #{value} (32-bit)");
                    Emit($"        LDA #${(value      ) & 0xFF:X2}");
                    Emit($"        STA {regBase}");
                    Emit($"        LDA #${(value >>  8) & 0xFF:X2}");
                    Emit($"        STA {regBase}+1");
                    Emit($"        LDA #${(value >> 16) & 0xFF:X2}");
                    Emit($"        STA {regBase}+2");
                    Emit($"        LDA #${(value >> 24) & 0xFF:X2}");
                    Emit($"        STA {regBase}+3");
                }
                else if (src.Type == OperandType.MEMORY)
                {
                    string addr = src.Value.ToString();
                    Emit($"        ; LOAD R{regNum}, [{addr}] (32-bit)");
                    Emit($"        LDA {addr}");
                    Emit($"        STA {regBase}");
                    Emit($"        LDA {addr}+1");
                    Emit($"        STA {regBase}+1");
                    Emit($"        LDA {addr}+2");
                    Emit($"        STA {regBase}+2");
                    Emit($"        LDA {addr}+3");
                    Emit($"        STA {regBase}+3");
                }
                else if (src.Type == OperandType.REGISTER)
                {
                    // 寄存器到寄存器复制
                    int srcReg = (int)src.Value;
                    string srcBase = GetRegBaseAddr(srcReg);
                    Emit($"        ; LOAD R{regNum}, R{srcReg} (32-bit)");
                    Emit($"        LDA {srcBase}");
                    Emit($"        STA {regBase}");
                    Emit($"        LDA {srcBase}+1");
                    Emit($"        STA {regBase}+1");
                    Emit($"        LDA {srcBase}+2");
                    Emit($"        STA {regBase}+2");
                    Emit($"        LDA {srcBase}+3");
                    Emit($"        STA {regBase}+3");
                }
                else if (src.Type == OperandType.INDIRECT)
                {
                    // 间接寻址：从地址指向的内存加载
                    string ptr = src.Value.ToString();
                    Emit($"        ; LOAD R{regNum}, @{ptr} (32-bit indirect)");
                    Emit($"        LDA ({ptr})");
                    Emit($"        STA {regBase}");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA ({ptr})");
                    Emit($"        STA {regBase}+1");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA ({ptr})");
                    Emit($"        STA {regBase}+2");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA ({ptr})");
                    Emit($"        STA {regBase}+3");
                }
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            // 32位存储：4字节操作
            if (src.Type == OperandType.REGISTER)
            {
                int srcReg = (int)src.Value;
                string srcBase = GetRegBaseAddr(srcReg);

                if (dst.Type == OperandType.MEMORY)
                {
                    string addr = dst.Value.ToString();
                    Emit($"        ; STORE [{addr}], R{srcReg} (32-bit)");
                    Emit($"        LDA {srcBase}");
                    Emit($"        STA {addr}");
                    Emit($"        LDA {srcBase}+1");
                    Emit($"        STA {addr}+1");
                    Emit($"        LDA {srcBase}+2");
                    Emit($"        STA {addr}+2");
                    Emit($"        LDA {srcBase}+3");
                    Emit($"        STA {addr}+3");
                }
                else if (dst.Type == OperandType.REGISTER)
                {
                    int dstReg = (int)dst.Value;
                    string dstBase = GetRegBaseAddr(dstReg);
                    Emit($"        ; STORE R{dstReg}, R{srcReg} (32-bit)");
                    Emit($"        LDA {srcBase}");
                    Emit($"        STA {dstBase}");
                    Emit($"        LDA {srcBase}+1");
                    Emit($"        STA {dstBase}+1");
                    Emit($"        LDA {srcBase}+2");
                    Emit($"        STA {dstBase}+2");
                    Emit($"        LDA {srcBase}+3");
                    Emit($"        STA {dstBase}+3");
                }
                else if (dst.Type == OperandType.INDIRECT)
                {
                    // 间接存储
                    string ptr = dst.Value.ToString();
                    Emit($"        ; STORE @{ptr}, R{srcReg} (32-bit indirect)");
                    Emit($"        LDA {srcBase}");
                    Emit($"        STA ({ptr})");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA {srcBase}+1");
                    Emit($"        STA ({ptr})");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA {srcBase}+2");
                    Emit($"        STA ({ptr})");
                    Emit($"        INC {ptr}");
                    Emit($"        LDA {srcBase}+3");
                    Emit($"        STA ({ptr})");
                }
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            // 32位加法：使用进位链
            Emit("        ; 32-bit ADD (with carry chain)");

            string dstBase = GetRegBaseAddr((int)dst.Value);
            string src1Base = GetRegBaseAddr((int)src1.Value);

            Emit("        CLC");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Base = GetRegBaseAddr((int)src2.Value);
                Emit($"        LDA {src1Base}");
                Emit($"        ADC {src2Base}");
                Emit($"        STA {dstBase}");
                Emit($"        LDA {src1Base}+1");
                Emit($"        ADC {src2Base}+1");
                Emit($"        STA {dstBase}+1");
                Emit($"        LDA {src1Base}+2");
                Emit($"        ADC {src2Base}+2");
                Emit($"        STA {dstBase}+2");
                Emit($"        LDA {src1Base}+3");
                Emit($"        ADC {src2Base}+3");
                Emit($"        STA {dstBase}+3");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        LDA {src1Base}");
                Emit($"        ADC #${value       & 0xFF:X2}");
                Emit($"        STA {dstBase}");
                Emit($"        LDA {src1Base}+1");
                Emit($"        ADC #${(value >> 8) & 0xFF:X2}");
                Emit($"        STA {dstBase}+1");
                Emit($"        LDA {src1Base}+2");
                Emit($"        ADC #${(value >> 16) & 0xFF:X2}");
                Emit($"        STA {dstBase}+2");
                Emit($"        LDA {src1Base}+3");
                Emit($"        ADC #${(value >> 24) & 0xFF:X2}");
                Emit($"        STA {dstBase}+3");
            }
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            // 32位减法：使用借位链
            Emit("        ; 32-bit SUB (with borrow chain)");

            string dstBase = GetRegBaseAddr((int)dst.Value);
            string src1Base = GetRegBaseAddr((int)src1.Value);

            Emit("        SEC");

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Base = GetRegBaseAddr((int)src2.Value);
                Emit($"        LDA {src1Base}");
                Emit($"        SBC {src2Base}");
                Emit($"        STA {dstBase}");
                Emit($"        LDA {src1Base}+1");
                Emit($"        SBC {src2Base}+1");
                Emit($"        STA {dstBase}+1");
                Emit($"        LDA {src1Base}+2");
                Emit($"        SBC {src2Base}+2");
                Emit($"        STA {dstBase}+2");
                Emit($"        LDA {src1Base}+3");
                Emit($"        SBC {src2Base}+3");
                Emit($"        STA {dstBase}+3");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        LDA {src1Base}");
                Emit($"        SBC #${value       & 0xFF:X2}");
                Emit($"        STA {dstBase}");
                Emit($"        LDA {src1Base}+1");
                Emit($"        SBC #${(value >> 8) & 0xFF:X2}");
                Emit($"        STA {dstBase}+1");
                Emit($"        LDA {src1Base}+2");
                Emit($"        SBC #${(value >> 16) & 0xFF:X2}");
                Emit($"        STA {dstBase}+2");
                Emit($"        LDA {src1Base}+3");
                Emit($"        SBC #${(value >> 24) & 0xFF:X2}");
                Emit($"        STA {dstBase}+3");
            }
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];

            // 32位比较：逐字节比较
            Emit("        ; 32-bit CMP");

            string src1Base = GetRegBaseAddr((int)src1.Value);

            if (src2.Type == OperandType.REGISTER)
            {
                string src2Base = GetRegBaseAddr((int)src2.Value);
                // 先比较高位，利用进位标志
                Emit($"        LDA {src1Base}+3");
                Emit($"        CMP {src2Base}+3");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}+2");
                Emit($"        CMP {src2Base}+2");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}+1");
                Emit($"        CMP {src2Base}+1");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}");
                Emit($"        CMP {src2Base}");
                Emit(".cmp_done:");
            }
            else if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        LDA {src1Base}+3");
                Emit($"        CMP #${(value >> 24) & 0xFF:X2}");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}+2");
                Emit($"        CMP #${(value >> 16) & 0xFF:X2}");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}+1");
                Emit($"        CMP #${(value >> 8) & 0xFF:X2}");
                Emit($"        BNE .cmp_done");
                Emit($"        LDA {src1Base}");
                Emit($"        CMP #${value       & 0xFF:X2}");
                Emit(".cmp_done:");
            }
        }

        protected override string MapRegister(int regNum)
        {
            return REGISTER_MAP.TryGetValue(regNum, out string reg) ? reg : $"R{regNum}";
        }
    }
}
